from __future__ import absolute_import
from taf.selenium.gnb.oam.coam.vdu.pages import v23R4
from taf.selenium.gnb.oam.coam.vdu import pages
from taf.selenium.gnb.oam.coam.vdu.pages.v22R1 import SnapshotPageViewPanelV22R1


class Diagnostic(v23R4.Diagnostic):
    def __init__(self, driver, version):
        super(Diagnostic, self).__init__(driver, version)
        self._instance_dict.update({"Snapshot": SnapshotPageV25R1(driver, version),
                                    "IPConnectivity": IPConnectivityV25R1(driver, version)})


class SnapshotPageV25R1(pages.SnapshotPage):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'Snapshot', 'Snapshot Collection']

    def __init__(self, driver, version):
        super(SnapshotPageV25R1, self).__init__(driver, version)
        self._view_panel = SnapshotPageViewPanelV25R1(driver, version)


class SnapshotPageViewPanelV25R1(SnapshotPageViewPanelV22R1):

    def __init__(self, driver, version):
        self.driver = driver
        super(SnapshotPageViewPanelV25R1, self).__init__(driver, version)

    def set_snapshot_collection_with_radio_box(self, coverage, save_location):
        self.click_enabled_element(self.locator.SNAPSHOT_DROPDOWN_BUTTON)
        self.click_enabled_element(self.locator.SNAPSHOT_SCOPE_XPATH.format(coverage))
        if save_location.lower() == "local":
            self.select_radiobox(self.locator.LOCAL_RADIO_BOX)
        else:
            self.select_radiobox(self.locator.REMOTE_RADIO_BOX)

    def _handle_session_renewal_pop_up(self, skip_session_renewal, renewal_password, timeout):
        if self.element_exists(self.locator.DYNAMIC_DIALOG, timeout=5):
            self.click_enabled_element(self.locator.CONTINUE_WITH_OUT_RENEWAL_CHECKBOX)
            self.click_enabled_element(self.locator.POP_UP_COLLECT_SNAPSHOT_BUTTON)


class IPConnectivityV25R1(pages.IPConnectivity):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'IP Connectivity']
